const byIndex = new Map();
for (const r of results) {
  if (!r || typeof r.index !== "number") continue;
  if (r.index < 53 || r.index > 92) continue;
  const v = r.value;
  if (v && typeof v === "object" && v.truncated === true) throw new Error("类目树第 " + r.index + " 片被截断（超过 browser.eval 的返回上限）—— 提高分片数后重新生成 book");
  const sv = v && typeof v === "object" && "value" in v ? v.value : v;
  if (typeof sv !== "string") throw new Error("类目树第 " + r.index + " 片不是字符串：" + JSON.stringify(sv).slice(0, 120));
  byIndex.set(r.index, sv);
}
const missing = want.filter((i) => !byIndex.has(i));
if (missing.length) throw new Error("类目树缺 " + missing.length + " 片，缺的步骤下标：" + missing.slice(0, 20).join(",") + " —— 宁可失败也不写半份文件");
const out = want.map((i) => byIndex.get(i)).join("");
JSON.parse(out); /* 拼完必须仍是合法 JSON —— 这条断言就是「没有丢片/错序」的证明 */
return out;

